import json
from collections import defaultdict
T=json.load(open('teams.json'))
drk={t['team']:(t['drtg_rk'],t['drtg']) for t in T}
nm={t['team']:t['name'] for t in T}
SRC={'fantasydata':'fantasydata.com','si.com':'si.com','espn':'espn.com','nba.com':'nba.com','cbssports':'cbssports.com','fantasyteamadvice':'fantasyteamadvice.com','landofbasketball':'landofbasketball.com','covers':'covers.com'}
rows=[]
# Lakers (already built & verified)
for r in json.load(open('lakers_last10.json'))['rows']:
    r=dict(r); r['team']='LAL'; r['team_name']=nm['LAL']; r['key']='LAL_'+r['key']; rows.append(r)
# Verified box-score blocks (dedupe on team|date; last 10 dates per team)
seen=set(); blocks=[]
for f in ('box_new.txt','box_b1.txt','box_pool.txt'):
    for b in open(f).read().split('## ')[1:]:
        l=b.strip().split('\n'); team,date=l[0].split('|')[:2]
        if (team,date) in seen: continue
        seen.add((team,date)); blocks.append((team,date,l))
keep=defaultdict(list)
for team,date,l in blocks: keep[team].append(date)
keep={t:set(sorted(d,reverse=True)[:10]) for t,d in keep.items()}
for team,date,l in blocks:
    if date not in keep[team]: continue
    team,date,opp,ha,res,src=l[0].split('|')
    for x in l[1:]:
        p=x.split('|'); mm,ss=p[1].split(':'); mins=round(int(mm)+int(ss)/60)
        v=list(map(int,p[2:]))
        rows.append(dict(key=f"{team}_{p[0].replace(' ','_').replace('.','')}_{date}",player=p[0],team=team,team_name=nm[team],
          date=date,opp=opp,opp_name=nm[opp],home_away='Home' if ha=='H' else 'Away',result=res,
          opp_def_rank=drk[opp][0],opp_def_eff=drk[opp][1],min=mins,pts=v[0],reb=v[1],ast=v[2],stl=v[3],blk=v[4],tpm=v[5],tpa=v[6],source=SRC[src],**({'tov':v[7]} if len(v)>7 else {})))
# keep each team's 10 most recent dates (Lakers rows come from lakers_last10.json + new blocks)
_d=defaultdict(set)
for r in rows: _d[r['team']].add(r['date'])
_keep={t:set(sorted(s,reverse=True)[:10]) for t,s in _d.items()}
rows=[r for r in rows if r['date'] in _keep[r['team']]]
# refresh opponent defense ranks for Lakers rows from teams.json (blocks already use it)
for r in rows:
    if r['key'].startswith('LAL_') and r['team']=='LAL' and r['opp'] in drk: r['opp_def_rank'],r['opp_def_eff']=drk[r['opp']]
# sanity: every game's player points == team final score
tot=defaultdict(int); fin={}
for r in rows:
    k=(r['team'],r['date']); tot[k]+=r['pts']; fin[k]=int(r['result'].split()[1].split('-')[0])
bad=[k for k in tot if tot[k]!=fin[k]]
assert not bad, bad
assert len({r['key'] for r in rows})==len(rows)
g=defaultdict(set)
for r in rows: g[r['team']].add(r['date'])
print({k:len(v) for k,v in g.items()}, len(rows))
