"""Nov 28 update: add Nov 27 box scores for 9 of 11 games (digestsports.com; each team's columns checked against the
team totals line) to the existing players_last10.json, keep each team's 10 most recent games, and refresh
opponent defensive rank/efficiency from the (unchanged, through Nov 25) team-defense file.
Lakers-Spurs and Pelicans-Clippers are NOT added: no verified box score (see Inputs)."""
import json,collections,unicodedata
OLD='data/players_last10.json'; DEF='data/nba_defense_2026_27.json'
SKIP={'Los Angeles Lakers','San Antonio Spurs','New Orleans Pelicans','LA Clippers'}
P=json.load(open(OLD)); rows=P['rows']
D=json.load(open(DEF))['rows']
drk={t['team']:(t['drtg_rk'],t['drtg']) for t in D}
nm={t['team']:t['name'] for t in D}
inv={v:k for k,v in nm.items()}; inv['Los Angeles Clippers']='LAC'
fold=lambda s:unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
known={}
for r in rows: known.setdefault((r['team'],fold(r['player'])),r['player'])
FIX={'Pacome Dadiet':'Pacôme Dadiet','Bobby Portis':'Bobby Portis Jr.','A.J. Green':'AJ Green','Ronald Holland II':'Ronald Holland','Jose Alvarado':'Jose Alvarado'}
unmatched=[]
def name(team,n):
    n=FIX.get(n,n); k=(team,fold(n))
    if k not in known: unmatched.append((team,n))
    return known.get(k,n)
new=[]
for g in open('raw.txt').read().split('## ')[1:]:
    L=g.strip().split('\n'); date,aw,hm,_=L[0].split('|')
    if aw in SKIP or hm in SKIP: continue
    blocks=[];cur=None
    for l in L[1:]:
        if l.startswith('TEAM:'): cur=[inv[l[5:].strip()],[]]; blocks.append(cur); continue
        p=l.split('|')
        if p[0]=='TOTALS': cur.append(int(p[2])); cur.append(list(map(int,p[2:]))); continue
        cur[1].append(p)
    (t1,p1,s1,T1),(t2,p2,s2,T2)=blocks
    homeab=inv[L[0].split('Home:')[1].strip()]
    for t,pl,s,T,o,os in [(t1,p1,s1,T1,t2,s2),(t2,p2,s2,T2,t1,s1)]:
        assert sum(int(x[2]) for x in pl)==s
        for i in range(8): assert sum(int(x[2+i]) for x in pl)==T[i],(t,i)
        res=f"{'W' if s>os else 'L'} {s}-{os}"
        for x in pl:
            mm,ss=x[1].split(':'); v=list(map(int,x[2:10])); pn=name(t,x[0])
            new.append(dict(key=f"{t}_{pn.replace(' ','_').replace('.','')}_{date}",player=pn,team=t,team_name=nm[t],date=date,opp=o,opp_name=nm[o],
              home_away='Home' if t==homeab else 'Away',result=res,opp_def_rank=drk[o][0],opp_def_eff=drk[o][1],min=round(int(mm)+int(ss)/60),
              pts=v[0],reb=v[1],ast=v[2],stl=v[3],blk=v[4],tpm=v[5],tpa=v[6],source='digestsports.com',tov=v[7]))
have={(r['team'],r['date']) for r in rows}
assert not ({(r['team'],r['date']) for r in new}&have)
rows=rows+new
d=collections.defaultdict(set)
for r in rows: d[r['team']].add(r['date'])
keep={t:set(sorted(s,reverse=True)[:10]) for t,s in d.items()}
rows=[r for r in rows if r['date'] in keep[r['team']]]
for r in rows: r['opp_def_rank'],r['opp_def_eff']=drk[r['opp']]
tot=collections.defaultdict(int);fin={}
for r in rows: k=(r['team'],r['date']); tot[k]+=r['pts']; fin[k]=int(r['result'].split()[1].split('-')[0])
assert all(tot[k]==fin[k] for k in tot),[k for k in tot if tot[k]!=fin[k]]
assert len({r['key'] for r in rows})==len(rows)
g=collections.defaultdict(set)
for r in rows: g[r['team']].add(r['date'])
assert all(len(v)==10 for v in g.values()) and len(g)==30,{k:len(v) for k,v in g.items()}
rows.sort(key=lambda r:(r['team'],r['date']))
